import {initialState,grade,eligible,shuffled,validateBackup,INTERVALS} from './domain.js';
import {load,save,storageDescription} from './storage.js';
function renderPractice(){$('#main').innerHTML=heading('ONE QUESTION AT A TIME','開始一場練習','先自己作答，再翻開答案。誠實判定，讓複習更有效。')+`<div class="split"><section class="panel"><h2>安排這次的考題</h2><div class="form-row"><label class="field" for="practice-category">選擇分類</label><select id="practice-category">${opts('',true)}</select></div><div class="form-row"><label class="field" for="practice-mode">出題範圍</label><select id="practice-mode"><option value="recommended">待熟練 ＋ 已到期的題目</option><option value="due">只練已到期的間隔複習</option><option value="all">全部題目（包含尚未到期）</option></select></div><div class="form-row"><label class="field" for="practice-count">本次題數</label><div class="row count-options"><button data-count="20" class="active">20 題</button><button data-count="30">30 題</button><input type="number" id="practice-count" aria-label="自訂題數" min="1" max="200" value="20"></div></div><p id="eligible-note" class="hint"></p><button id="start-practice" class="primary wide">開始練習 →</button></section><aside><section class="panel"><span class="tag">熟練機制</span><h2 style="margin-top:16px">一步一步，記得更久。</h2><ol class="spaced-list"><li>連續答對 <strong>${state.target} 次</strong>，進入間隔複習。</li><li>依序在 1、3、7、14、30 天後再練。</li><li>答錯重置連續答對次數，回到待熟練。</li></ol><p class="muted note">每場題目不重複。沒有答案的題目，補上答案後才會加入考題。</p></section></aside></div>`;const update=()=>{const n=eligible(state.cards,$('#practice-category').value,$('#practice-mode').value).length,want=Number($('#practice-count').value);$('#eligible-note').textContent=n?`可出題 ${n} 題。本次將隨機選取 ${Math.min(Number.isInteger(want)&&want>0?want:0,n)} 題。`:'目前沒有可出的題目，請先新增題目與答案，或更改範圍。';$('#start-practice').disabled=!n;document.querySelectorAll('[data-count]').forEach(b=>b.classList.toggle('active',Number(b.dataset.count)===want));};['#practice-category','#practice-mode','#practice-count'].forEach(s=>$(s).oninput=update);document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{$('#practice-count').value=b.dataset.count;update();});$('#start-practice').onclick=safely(()=>startPractice($('#practice-category').value,$('#practice-mode').value,Number($('#practice-count').value)));update();}
function startPractice(category,mode,count){if(!Number.isInteger(count)||count<1||count>200)throw Error('題數請輸入 1 到 200 的整數。');if(!['all','due','recommended'].includes(mode)||category&&!state.categories.includes(category))throw Error('無效的出題範圍。');const pool=eligible(state.cards,category,mode);if(!pool.length)throw Error('這個範圍沒有已配對答案的題目。');session={ids:shuffled(pool).slice(0,count).map(c=>c.id),index:0,correct:0,revealed:false,answering:false};tab='practice';render();return{count:session.ids.length};}
function confirmLeave(then){if(session?.answering){toast('正在儲存作答，請稍候。');return;}dialog('結束這次練習？','<p>已作答的結果都已儲存，尚未作答的題目不會計分。</p><div class="actions"><button id="keep-practice">繼續練習</button><button id="leave-practice" class="primary">結束練習</button></div>');$('#keep-practice').onclick=()=>modal.close();$('#leave-practice').onclick=()=>{session=null;modal.close();then();};}
function renderSession(){if(session.index>=session.ids.length){const total=session.ids.length,correct=session.correct;$('#main').innerHTML=`<section class="empty session"><span class="empty-icon">✓</span><h1>這次的練習，完成了。</h1><p>共 ${total} 題 · 答對 ${correct} 題 · 答錯 ${total-correct} 題</p><h2 style="color:var(--blue);font-size:46px">${Math.round(correct/total*100)}<small style="font-size:20px">%</small></h2><p>每次判定都已儲存，題目的熟練度與下次複習時間也已更新。</p><button id="finish-practice" class="primary">回到練習安排</button></section>`;$('#finish-practice').onclick=()=>{session=null;render();};return;}const c=state.cards.find(c=>c.id===session.ids[session.index]);$('#main').innerHTML=`<div class="session"><div class="session-top"><h2>第 ${session.index+1} / ${session.ids.length} 題</h2><button id="end-session">結束練習</button></div><div class="progress" role="progressbar" aria-valuenow="${session.index}" aria-valuemin="0" aria-valuemax="${session.ids.length}"><div style="width:${session.index/session.ids.length*100}%"></div></div><section class="question-sheet"><div class="row between"><span class="tag">${esc(c.category)}</span><span class="muted">${c.stage>=0?'間隔複習':`連續答對 ${c.streak} / ${state.target}`}</span></div><h2>${esc(c.title)}</h2><img src="${c.question}" alt="本題題目">${session.revealed?`<div class="answer-sheet"><span class="tag green">答案卡</span><img src="${c.answer}" alt="本題答案"><p class="muted">對照答案，這題你答對了嗎？</p></div>`:'<p class="muted" style="text-align:center">先在紙上或心中作答，準備好後再看答案。</p>'}</section>${session.revealed?'<div class="grade-buttons"><button class="incorrect" id="grade-wrong">× 答錯了，再練習</button><button class="correct" id="grade-correct">✓ 答對了</button></div>':'<button class="primary wide" id="reveal-answer">翻開答案卡</button>'}</div>`;$('#end-session').onclick=()=>confirmLeave(render);$('#reveal-answer')?.addEventListener('click',()=>{session.revealed=true;renderSession();});const answer=correct=>safely(async()=>{if(session.answering)return;session.answering=true;document.querySelectorAll('.grade-buttons button').forEach(b=>b.disabled=true);try{const at=Date.now(),next=grade(c,correct,state.target,at);await commit({...state,cards:state.cards.map(x=>x.id===c.id?next:x),history:[...state.history,{cardId:c.id,category:c.category,correct,at}]});session.correct+=correct?1:0;session.index++;session.revealed=false;}finally{session.answering=false;renderSession();}});if(session.revealed){$('#grade-wrong').onclick=answer(false);$('#grade-correct').onclick=answer(true);}}
function renderStats(){const n=counts(),total=state.history.length,correct=state.history.filter(h=>h.correct).length,pct=n.total?Math.round(n.spaced/n.total*100):0;const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);const end=new Date(d);end.setDate(end.getDate()+1);const history=state.history.filter(h=>h.at>=d.getTime()&&h.at<end.getTime());return{label:`${d.getMonth()+1}/${d.getDate()}`,right:history.filter(h=>h.correct).length,wrong:history.filter(h=>!h.correct).length};});const max=Math.max(1,...days.flatMap(d=>[d.right,d.wrong]));$('#main').innerHTML=heading('YOUR LEARNING, AT A GLANCE','看見自己的進步',total?`累積作答 ${total} 次，答對 ${correct} 次，答錯 ${total-correct} 次。`:'完成第一次練習後，這裡會出現你的學習紀錄。')+metrics()+`<div class="split"><section class="panel"><div class="row between"><h2>最近 7 天的練習</h2><span class="muted">作答次數</span></div><div class="chart" role="img" aria-label="最近七天作答紀錄：${days.map(d=>`${d.label} 答對 ${d.right} 次、答錯 ${d.wrong} 次`).join('；')}">${days.map(d=>`<div class="chart-col"><div class="chart-bars"><div class="bar" style="height:${d.right/max*100}%" title="答對 ${d.right} 次"></div><div class="bar wrong" style="height:${d.wrong/max*100}%" title="答錯 ${d.wrong} 次"></div></div><small>${d.label}</small><small>${d.right} / ${d.wrong}</small></div>`).join('')}</div><div class="legend"><span><i></i>答對</span><span><i class="wrong"></i>答錯</span></div></section><section class="panel"><h2>題目熟練度</h2><div class="donut" style="background:conic-gradient(#155eeb ${pct}%,#e8edf5 0)" role="img" aria-label="${pct}% 的題目已進入間隔複習"><div><strong>${pct}%</strong><small class="muted">已進入間隔複習</small></div></div><p class="muted" style="text-align:center">${n.spaced} 題已熟練 · ${n.learning} 題待熟練</p></section></div><section class="panel"><h2>各分類掌握情況</h2>${state.categories.map(cat=>{const cards=state.cards.filter(c=>c.category===cat),mastered=cards.filter(c=>c.stage>=0).length;return`<div class="subject-line"><div class="row between"><span>${esc(cat)}</span><span class="muted">${mastered} / ${cards.length} 題已熟練</span></div><div class="progress"><div style="width:${cards.length?mastered/cards.length*100:0}%"></div></div></div>`;}).join('')}</section>`;}
function renderSettingsContent(){$('#main').innerHTML=heading('MAKE IT YOURS','設定與資料','調整練習節奏，讓題庫跟著你走。')+`<div class="split"><div><section class="panel"><h2>自訂分類</h2><div>${state.categories.map(c=>`<div class="row between category-row"><span>${esc(c)} <small class="muted">${state.cards.filter(x=>x.category===c).length} 題</small></span><div class="row"><button data-rename="${esc(c)}" style="padding:6px 10px;font-size:14px">更名</button><button data-remove="${esc(c)}" style="padding:6px 10px;font-size:14px" ${state.categories.length===1||state.cards.some(x=>x.category===c)?'disabled':''}>刪除</button></div></div>`).join('')}</div><form id="category-form" class="row" style="margin-top:20px"><input id="new-category" aria-label="新增分類名稱" placeholder="例如：自然、社會" maxlength="30" required><button class="primary" type="submit" style="white-space:nowrap">新增</button></form><p class="muted">有題目的分類需先移動或刪除題目，才能刪除分類。</p></section><section class="panel"><h2>熟練門檻</h2><label class="field" for="target-count">連續答對幾次後，進入間隔複習？</label><div class="row"><input id="target-count" type="number" min="1" max="10" value="${state.target}"><button id="save-target" style="white-space:nowrap">儲存</button></div><p class="muted">調整套用在下一次作答；已進入間隔複習的題目不受影響。答錯一律歸零。30 天階段後持續每 30 天複習。</p></section></div><section class="panel" style="align-self:start"><span class="tag">資料搬移</span><h2 style="margin-top:16px">把你的努力，一起帶走。</h2><p>備份包含題目與答案照片、分類、熟練度和所有練習紀錄。</p><div class="form-row"><button class="primary wide" id="export-data">↓ 匯出完整備份</button></div><div class="form-row"><button class="wide" id="import-data">↑ 匯入備份檔案</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p class="hint">在另一台裝置開啟拾題，選擇「匯入備份檔案」即可搬移。匯入前會顯示摘要，確認後取代目前資料。</p><p class="muted">${storageDescription}</p></section></div>`;$('#category-form').onsubmit=safely(async e=>{e.preventDefault();await addCategory($('#new-category').value);renderSettings();toast('分類已新增');});document.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>{const old=b.dataset.rename;dialog('更改分類名稱',`<label class="field" for="rename-category">分類名稱</label><input id="rename-category" maxlength="30" value="${esc(old)}"><div class="actions"><button class="primary" id="confirm-rename">儲存名稱</button></div>`);$('#confirm-rename').onclick=safely(async()=>{const name=$('#rename-category').value.trim();if(!name||name.length>30)throw Error('名稱請輸入 1 到 30 個字。');if(name!==old&&state.categories.includes(name))throw Error('已經有這個分類。');await commit({...state,categories:state.categories.map(c=>c===old?name:c),cards:state.cards.map(c=>c.category===old?{...c,category:name}:c),history:state.history.map(h=>h.category===old?{...h,category:name}:h)});if(filter===old)filter=name;modal.close();renderSettings();});});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=safely(async()=>{const cat=b.dataset.remove;if(state.categories.length<2||state.cards.some(c=>c.category===cat))throw Error('只能刪除沒有題目的分類，且至少需保留一個分類。');await commit({...state,categories:state.categories.filter(c=>c!==cat)});if(filter===cat)filter='';renderSettings();}));$('#save-target').onclick=safely(async()=>{const target=Number($('#target-count').value);if(!Number.isInteger(target)||target<1||target>10)throw Error('請輸入 1 到 10 的整數。');await commit({...state,target});toast('熟練門檻已儲存');});$('#export-data').onclick=()=>{const blob=new Blob([JSON.stringify(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`拾題備份-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('備份檔案已準備下載');};$('#import-data').onclick=()=>$('#import-file').click();$('#import-file').onchange=safely(async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>200*1024*1024)throw Error('備份超過 200 MB，無法在此裝置一次匯入。');let data;try{data=JSON.parse(await file.text());}catch{throw Error('檔案不是有效的 JSON 備份。');}const next=validateBackup(data);dialog('確認匯入這份備份？',`<p>備份包含 <strong>${next.cards.length} 道題目</strong>、${next.categories.length} 個分類、${next.history.length} 次練習紀錄。</p><p class="hint">將取代目前 ${state.cards.length} 道題目與練習紀錄。建議先匯出目前資料，避免遺失。</p><div class="actions"><button id="cancel-import">取消</button><button class="primary" id="confirm-import">取代並匯入</button></div>`);$('#cancel-import').onclick=()=>modal.close();$('#confirm-import').onclick=safely(async()=>{await commit(next);filter='';statusFilter='all';session=null;modal.close();render();toast('匯入完成，照片與練習進度已還原');});});}
async function addCategory(input){if(typeof input!=='string')throw Error('分類名稱必須是文字。');const name=input.trim();if(!name||name.length>30)throw Error('名稱請輸入 1 到 30 個字。');if(state.categories.includes(name))throw Error('已經有這個分類。');if(state.categories.length>=100)throw Error('分類最多 100 個。');await commit({...state,categories:[...state.categories,name]});return{name};}
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=ms=>new Date(ms).toLocaleDateString('zh-TW',{month:'short',day:'numeric'});
let state=initialState(),tab='library',filter='',statusFilter='all',session=null,busy=false,timer;
const app=$('#app'),modal=$('#modal');
async function init(){try{const saved=await load();state=saved||initialState();render();registerTools();if(!saved){dialog('開始使用拾題','<p>這個版本將照片與進度保存在目前裝置的瀏覽器，你可以用完整備份在裝置間搬移。</p><p class="hint">沒有自動雲端同步。建議定期匯出備份，避免清除瀏覽器資料時遺失題庫。</p><div class="actions"><button class="primary" id="accept-local">使用此裝置儲存</button></div>');$('#accept-local').onclick=safely(async()=>{await commit(state);modal.close();navigator.storage?.persist?.().catch(()=>{});});}}catch(error){const main=$('#main')||$('main');main.innerHTML=`<section class="empty"><h2>暫時無法讀取題庫</h2><p>${esc(error.message)}</p><button onclick="location.reload()">重新載入</button></section>`;}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'get_question_book_summary',description:'讀取題目數量、熟練度、分類和練習次數。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({...counts(),categories:state.categories,attempts:state.history.length,target:state.target})},{name:'add_question_category',description:'新增錯題分類並更新畫面。',inputSchema:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:30}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(session)throw Error('請先結束目前練習。');const result=await addCategory(input?.name);render();return result;}},{name:'start_question_practice',description:'開始練習並顯示第一道題目，不提交作答。',inputSchema:{type:'object',properties:{category:{type:'string'},count:{type:'integer',minimum:1,maximum:200},mode:{type:'string',enum:['recommended','due','all']}},required:['count','mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(session)throw Error('請先完成或結束目前的練習。');return startPractice(input?.category||'',input?.mode,input?.count);}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});
init();
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',4200);}
function addResetControl(){
 const section=document.createElement('section');section.className='panel';
 section.innerHTML='<h2>重置資料庫</h2><p>清除這個瀏覽器中的所有題目、照片與練習紀錄，並將分類及熟練門檻恢復預設值。</p><button class="danger" id="reset-database">重置資料庫</button>';
 $('#main').append(section);
 $('#reset-database').onclick=()=>{
  dialog('確定重置資料庫？',`<p>將永久清除目前的 <strong>${state.cards.length} 道題目</strong>（含題目與答案照片）、<strong>${state.history.length} 筆作答紀錄</strong>及所有熟練進度。</p><p>分類恢復為國文、英文、數學，連續答對門檻恢復為 3 次。只影響目前瀏覽器，已匯出的備份不受影響。</p><p class="hint">此操作無法復原。需要保留資料時，請先匯出備份。</p><label class="field" for="reset-confirmation">請輸入「重置」以確認</label><input id="reset-confirmation" autocomplete="off" placeholder="重置"><div class="actions"><button id="backup-before-reset">先匯出備份</button><button id="cancel-reset">取消</button><button class="danger" id="confirm-reset" disabled>清除全部資料</button></div>`);
  $('#backup-before-reset').onclick=()=>$('#export-data').click();
  $('#cancel-reset').onclick=()=>modal.close();
  $('#reset-confirmation').oninput=e=>{$('#confirm-reset').disabled=e.target.value.trim()!=='重置';};
  $('#confirm-reset').onclick=safely(async()=>{
   if($('#reset-confirmation').value.trim()!=='重置')throw Error('請輸入「重置」以確認。');
   await commit(initialState());
   filter='';statusFilter='all';session=null;modal.close();render();toast('資料庫已重置，所有題目與練習紀錄已清除');
  });
 };
}
function dialog(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" aria-label="關閉">×</button></div>${body}`;modal.querySelector('.close').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
async function commit(next){if(busy)throw Error('正在儲存，請稍候。');busy=true;try{await save(next);state=next;}finally{busy=false;}}
function safely(fn){return async e=>{const b=e?.currentTarget;try{if(b?.tagName==='BUTTON')b.disabled=true;await fn(e);}catch(error){toast(error.message||'操作失敗，請再試一次。');}finally{if(b?.isConnected)b.disabled=false;}};}
function opts(selected='',all=false){return(all?'<option value="">全部分類</option>':'')+state.categories.map(c=>`<option ${c===selected?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('');}
function cardStatus(c){return!c.answer?'待補答案':c.stage>=0?(c.due<=Date.now()?'今日待複習':'間隔複習中'):'待熟練';}
function counts(){return{total:state.cards.length,learning:state.cards.filter(c=>c.stage<0).length,spaced:state.cards.filter(c=>c.stage>=0).length,due:state.cards.filter(c=>c.answer&&c.stage>=0&&c.due<=Date.now()).length};}
function metrics(){const n=counts();return`<div class="stats-row">${[['收藏的錯題',n.total],['待熟練',n.learning],['間隔複習中',n.spaced],['今日到期',n.due]].map(([s,n])=>`<div class="stat"><label>${s}</label><strong>${n}<small> 題</small></strong></div>`).join('')}</div>`;}
function render(){app.innerHTML=`<header><a class="brand" href="#">▣ 拾題 <small>錯題本</small></a><span>每一道錯題，都有下一次進步。</span></header><nav aria-label="主要選單">${[['library','▦','我的題庫'],['practice','▹','開始練習'],['stats','◷','學習統計'],['settings','⚙','設定與資料']].map(([key,icon,label])=>`<button data-tab="${key}" class="${tab===key?'active':''}" aria-current="${tab===key?'page':'false'}">${icon}　${label}</button>`).join('')}</nav><main id="main"></main><footer>拾題 · 讓每次練習都算數</footer>`;app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const go=()=>{tab=b.dataset.tab;render();};if(session&&tab==='practice'&&b.dataset.tab!=='practice')confirmLeave(go);else go();});$('.brand').onclick=e=>{e.preventDefault();const go=()=>{tab='library';render();};session?confirmLeave(go):go();};if(tab==='library')renderLibrary();else if(tab==='practice')session?renderSession():renderPractice();else if(tab==='stats')renderStats();else renderSettings();}
function heading(kicker,title,description,action=''){return`<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p style="margin:0">${description}</p></div>${action}</div>`;}
function renderLibrary(){const cards=state.cards.filter(c=>(!filter||c.category===filter)&&(statusFilter==='all'||(statusFilter==='missing'?!c.answer:statusFilter==='spaced'?c.stage>=0:c.stage<0)));$('#main').innerHTML=heading('MY QUESTION BOOK','我的題庫','把值得再練一次的題目，留在這裡。','<button class="primary" id="new-card">＋ 新增題目</button>')+metrics()+`<div class="toolbar"><div class="chips">${['',...state.categories].map(c=>`<button class="chip ${filter===c?'active':''}" data-category="${esc(c)}">${esc(c||'全部')} <span style="opacity:.65">${state.cards.filter(x=>!c||x.category===c).length}</span></button>`).join('')}</div><select id="status-filter" aria-label="熟練狀態" style="width:auto"><option value="all">所有狀態</option><option value="learning">待熟練</option><option value="spaced">間隔複習中</option><option value="missing">待補答案</option></select></div>${cards.length?`<div class="cards">${cards.map(c=>`<button class="card" data-card="${esc(c.id)}"><img class="card-photo" src="${c.question}" alt="${esc(c.title)}的題目" loading="lazy"><div class="card-body"><div class="card-top"><span class="tag">${esc(c.category)}</span><span class="tag ${!c.answer?'orange':c.stage>=0?'green':''}">${cardStatus(c)}</span></div><h3>${esc(c.title)}</h3>${c.stage<0?`<div class="meter">${Array.from({length:state.target},(_,i)=>`<i class="${i<c.streak?'on':''}"></i>`).join('')}</div><div class="row between muted"><span>連續答對 ${c.streak} / ${state.target}</span><span>答錯 ${c.mistakes} 次</span></div>`:`<div class="row between muted"><span>下次複習 ${date(c.due)}</span><span>${INTERVALS[c.stage]} 天間隔</span></div>`}</div></button>`).join('')}</div>`:`<section class="empty"><span class="empty-icon">＋</span><h2>${state.cards.length?'這裡還沒有符合的題目':'從第一道錯題開始'}</h2><p>拍下題目，用手指框選範圍。答案可以一起加入，也可以之後再補。</p><button class="primary" id="empty-add">拍照 / 選擇圖片</button></section>`}`;$('#new-card').onclick=()=>editCard();$('#empty-add')?.addEventListener('click',()=>editCard());$('#status-filter').value=statusFilter;$('#status-filter').onchange=e=>{statusFilter=e.target.value;renderLibrary();};document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{filter=b.dataset.category;renderLibrary();});document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>viewCard(b.dataset.card));}
function viewCard(id){const c=state.cards.find(c=>c.id===id);if(!c)return;dialog(esc(c.title),`<div class="row between"><span class="tag">${esc(c.category)}</span><span class="muted">${cardStatus(c)}</span></div><h3>題目卡</h3><img class="photo-preview" src="${c.question}" alt="題目"><h3>答案卡</h3>${c.answer?`<img class="photo-preview" src="${c.answer}" alt="答案">`:'<p class="hint">還沒有答案，補上後就可以加入練習。</p>'}<p class="muted">練習 ${c.attempts} 次 · 答錯 ${c.mistakes} 次 · 建立於 ${date(c.created)}</p><div class="actions"><button class="danger" id="delete-card">刪除題目</button><button class="primary" id="edit-card">${c.answer?'編輯卡片':'補上答案'}</button></div>`);$('#edit-card').onclick=()=>editCard(c);$('#delete-card').onclick=()=>{dialog('刪除這道題目？',`<p>「${esc(c.title)}」的照片將被刪除。過去的練習次數會保留在統計中。</p><div class="actions"><button id="cancel-delete">取消</button><button class="danger" id="confirm-delete">刪除題目</button></div>`);$('#cancel-delete').onclick=()=>viewCard(c.id);$('#confirm-delete').onclick=safely(async()=>{await commit({...state,cards:state.cards.filter(x=>x.id!==c.id)});modal.close();render();toast('題目已刪除');});};}
function editCard(existing){const draft=existing?{...existing}:{title:'',category:filter||state.categories[0],question:null,answer:null};function show(){dialog(existing?'編輯題目卡':'新增題目卡',`<div class="form-row"><label class="field" for="card-title">題目名稱</label><input id="card-title" maxlength="100" placeholder="例如：一元二次方程式・第 5 題" value="${esc(draft.title)}"></div><label class="field" for="card-category">分類</label><select id="card-category">${opts(draft.category)}</select>${['question','answer'].map((key,i)=>`<div class="upload"><h3>${i?'02 答案卡 <span class="muted">（可稍後補上）</span>':'01 題目卡'}</h3>${draft[key]?`<img class="photo-preview" src="${draft[key]}" alt="${i?'答案':'題目'}預覽">`:`<p>${i?'拍下解答，和這道題目配對。':'拍照或選取照片，拖曳框選題目範圍。'}</p>`}<div class="row" style="justify-content:center;flex-wrap:wrap"><button data-upload="${key}" data-camera="true">${draft[key]?'重拍':'拍照'}</button><button data-upload="${key}">選擇圖片</button></div></div>`).join('')}<p class="muted">照片會先縮小以節省空間；儲存前可檢查清晰度。</p><div class="actions"><button id="cancel-edit">取消</button><button class="primary" id="save-card" ${!draft.question?'disabled':''}>儲存卡片</button></div>`);$('#card-title').oninput=e=>draft.title=e.target.value;$('#card-category').onchange=e=>draft.category=e.target.value;$('#cancel-edit').onclick=()=>modal.close();modal.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='image/*';if(b.dataset.camera)input.setAttribute('capture','environment');input.onchange=safely(async()=>{if(input.files[0])await cropImage(input.files[0],url=>{draft[b.dataset.upload]=url;show();},show);});input.click();});$('#save-card').onclick=safely(async()=>{if(!draft.question)throw Error('請先加入題目照片。');const c={...draft,title:draft.title.trim()||`${draft.category}錯題 ${state.cards.length+1}`};if(!existing)Object.assign(c,{id:crypto.randomUUID(),streak:0,stage:-1,due:null,attempts:0,mistakes:0,created:Date.now()});await commit({...state,cards:existing?state.cards.map(x=>x.id===c.id?c:x):[c,...state.cards]});modal.close();render();toast(existing?'卡片已更新':'題目已收藏');});}show();}
async function cropImage(file,onSave,onCancel){if(!file.type.startsWith('image/'))throw Error('請選擇照片檔案。');if(file.size>35*1024*1024)throw Error('照片太大，請選擇 35 MB 以下的圖片。');const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('無法讀取這張照片，請改用 JPG、PNG 或 WebP。'));img.src=url;});}catch(e){URL.revokeObjectURL(url);throw e;}dialog('框選要保留的範圍','<p class="hint">用手指或滑鼠拖曳畫出方框；重新拖曳即可重選。也可以直接保留整張照片。</p><div class="crop-wrap"><canvas id="crop" aria-label="拖曳框選照片範圍"></canvas></div><p class="muted" id="crop-state" aria-live="polite">目前保留整張照片</p><div class="actions"><button id="cancel-crop">取消</button><button id="full-crop">選取全圖</button><button class="primary" id="use-crop">使用這個範圍</button></div>');const canvas=$('#crop'),ctx=canvas.getContext('2d'),scale=Math.min(1,1800/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);let start=null,box={x:0,y:0,w:canvas.width,h:canvas.height};function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);ctx.fillStyle='#14274488';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.save();ctx.beginPath();ctx.rect(box.x,box.y,box.w,box.h);ctx.clip();ctx.drawImage(img,0,0,canvas.width,canvas.height);ctx.restore();ctx.strokeStyle='#4c9aff';ctx.lineWidth=Math.max(3,canvas.width/180);ctx.strokeRect(box.x,box.y,box.w,box.h);}function point(e){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(canvas.width,(e.clientX-r.left)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(e.clientY-r.top)*canvas.height/r.height))};}canvas.onpointerdown=e=>{e.preventDefault();start=point(e);canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!start)return;const p=point(e);box={x:Math.min(p.x,start.x),y:Math.min(p.y,start.y),w:Math.abs(p.x-start.x),h:Math.abs(p.y-start.y)};draw();};canvas.onpointerup=()=>{if(!start)return;start=null;if(box.w<15||box.h<15)box={x:0,y:0,w:canvas.width,h:canvas.height};$('#crop-state').textContent=`已選取 ${Math.round(box.w)} × ${Math.round(box.h)} 像素`;draw();};canvas.onpointercancel=()=>{start=null;};$('#full-crop').onclick=()=>{box={x:0,y:0,w:canvas.width,h:canvas.height};$('#crop-state').textContent='目前保留整張照片';draw();};$('#cancel-crop').onclick=onCancel;modal.querySelector('.close').onclick=onCancel;$('#use-crop').onclick=safely(()=>{if(box.w<15||box.h<15)throw Error('範圍太小，請重新框選。');const out=document.createElement('canvas');out.width=Math.round(box.w);out.height=Math.round(box.h);const context=out.getContext('2d');context.fillStyle='white';context.fillRect(0,0,out.width,out.height);context.drawImage(img,box.x/scale,box.y/scale,box.w/scale,box.h/scale,0,0,out.width,out.height);onSave(out.toDataURL('image/jpeg',.9));});draw();URL.revokeObjectURL(url);}

function renderSettings(){renderSettingsContent();addResetControl();}
